183	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
184	// 结果历史都必须自洽，否则整个存储拒绝打开。
185	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
186		out := make(map[string]*campaignState, len(disk))
187		for id, dc := range disk {
188			if id == "" || dc.ID != id {
189				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
190			}
191			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
192				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
193			}
194			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
195				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
196			}
197			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
198				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
199			}
200			if _, ok := s.versions[dc.Target]; !ok {
201				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
202			}
203			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
204				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
205			}
206			if dc.IDScheme != opIDSchemeLegacy && dc.IDScheme != opIDSchemeV2 {
207				return fmt.Errorf("%w: campaign %s unknown operation id scheme", ErrCorruptStorage, id)
208			}
209			if dc.Ended == (dc.Status == CampaignRunning) {
210				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
211			}
212			if len(dc.Devices) == 0 {
213				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
214			}
215			c := &campaignState{
216				ID:                dc.ID,
217				Operator:          dc.Operator,
218				Target:            dc.Target,
219				CreatedAt:         dc.CreatedAt,
220				BatchSize:         dc.BatchSize,
221				WindowStart:       dc.WindowStart,
222				WindowEnd:         dc.WindowEnd,
223				Deadline:          dc.Deadline,
224				RollbackOnFailure: dc.RollbackOnFailure,
225				idScheme:          dc.IDScheme,
226				LastTime:          dc.LastTime,
227				Status:            dc.Status,
228				Ended:             dc.Ended,
229				EndedAt:           dc.EndedAt,
230				index:             map[string]int{},
231			}
232			if c.LastTime.IsZero() {
233				c.LastTime = c.CreatedAt
234			}
235			if c.LastTime.Before(c.CreatedAt) {
236				return fmt.Errorf("%w: campaign %s last time before creation", ErrCorruptStorage, id)
237			}
238			seen := map[string]bool{}
239			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
240			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
241			expected := map[string]expectedHist{}
242			for i, dd := range dc.Devices {
243				if dd.DeviceID == "" || seen[dd.DeviceID] {
244					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
245				}
246				seen[dd.DeviceID] = true
247				if _, ok := s.devices[dd.DeviceID]; !ok {
248					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
249				}
250				if dd.Batch != i/dc.BatchSize {
251					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
252				}
253				if !validDeviceStatus(dd.Status) {
254					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
255				}
256				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
257					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
258				}
259				if dc.IDScheme == opIDSchemeV2 {
260					// 新方案：标识必须是无歧义编码且恰好归属本活动、本设备、本阶段。
261					if !validV2OpID(dd.Download.ID, id, dd.DeviceID, StageDownload) ||
262						!validV2OpID(dd.Install.ID, id, dd.DeviceID, StageInstall) ||
263						!validV2OpID(dd.Rollback.ID, id, dd.DeviceID, StageRollback) {
264						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
265					}
266				} else {
267					wantDL := operationID(id, dd.DeviceID, StageDownload)
268					wantIN := operationID(id, dd.DeviceID, StageInstall)
269					wantRB := operationID(id, dd.DeviceID, StageRollback)
270					if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
271						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
272					}
273					if dc.RollbackOnFailure {
274						if dd.Rollback.ID != wantRB {
275							return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
276						}
277					} else if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
278						// 未开启回滚的旧活动：回滚标识允许缺省或等于旧稳定标识。
279						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
280					}
281				}
282				if !dc.RollbackOnFailure {
283					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展。
284					if dd.RollbackTarget != "" ||
285						dd.Rollback.Claimed || dd.Rollback.HasResult ||
286						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
287						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
288						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
289					}
290				}
291				// 终态设备必须带时间；失败还须带阶段与原因。
292				if isTerminal(dd.Status) && dd.At.IsZero() {
293					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
294				}
295				if dd.Status == DeviceFailed && dd.Reason == "" {
296					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
297				}
298				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
299					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
300					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
301				}
302				if dd.Status == DeviceSucceeded &&
303					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
304					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
305				}
306				if dd.Status == DeviceFailed {
307					failedOp := dd.Download
308					if dd.Phase == StageInstall {
309						failedOp = dd.Install
310					}
311					if !failedOp.HasResult || failedOp.Success {
312						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
313					}
314				}
315				if dd.Status == DeviceReady && !(dd.Download.HasResult && dd.Download.Success) {
316					return fmt.Errorf("%w: campaign %s ready device without download", ErrCorruptStorage, id)
317				}
318				ops := []diskOp{dd.Download, dd.Install}
319				if dc.RollbackOnFailure {
320					ops = append(ops, dd.Rollback)
321				}
322				for _, o := range ops {
323					if o.HasResult {
324						if !o.Claimed {
325							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
326						}
327						if o.At.IsZero() {
328							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
329						}
330						if !o.Success && o.Reason == "" {
331							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
332						}
333					}
334					if o.Claimed && o.ClaimedAt.IsZero() {
335						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
336					}
337				}
338				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
339					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
340				}
341				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
342					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
343				}
344				if dd.Install.HasResult && dd.Install.Success {
345					if dd.Install.ResultVersion != dc.Target {
346						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
347					}
348					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
349						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
350					}
351				}
352				if dc.RollbackOnFailure {
353					if err := validateRollbackDisk(id, dd); err != nil {
354						return err
355					}
356				}
357				rbOp := decodeOp(dd.Rollback)
358				if !dc.RollbackOnFailure {
359					// 与创建路径一致：内存中始终持有本方案稳定的回滚操作标识。
360					if dc.IDScheme == opIDSchemeV2 {
361						rbOp = opState{ID: dd.Rollback.ID}
362					} else {
363						rbOp = opState{ID: operationID(id, dd.DeviceID, StageRollback)}
364					}
365				}
366				cd := &campaignDevice{
367					DeviceID:       dd.DeviceID,
368					Batch:          dd.Batch,
369					Status:         dd.Status,
370					Phase:          dd.Phase,
371					Reason:         dd.Reason,
372					At:             dd.At,
373					Download:       decodeOp(dd.Download),
374					Install:        decodeOp(dd.Install),
375					Rollback:       rbOp,
376					RollbackTarget: dd.RollbackTarget,
377				}
378				c.index[cd.DeviceID] = len(c.Devices)
379				c.Devices = append(c.Devices, cd)
380				// 每个已有结果的操作都应当恰好对应一条结果历史；
381				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
382				addExpected := func(o diskOp, stage string) {
383					if !o.HasResult {
384						return
385					}
386					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
387				}
388				addExpected(dd.Download, StageDownload)
389				addExpected(dd.Install, StageInstall)
390				if dc.RollbackOnFailure {
391					addExpected(dd.Rollback, StageRollback)
392				}
393			}
394			// seenHistory 记录已经与保存历史对过账的操作标识。
395			seenHistory := map[string]bool{}
396			var prevAt time.Time
397			for i, dr := range dc.Results {
398				if dr.At.IsZero() {
399					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
400				}
401				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
402				if i > 0 && dr.At.Before(prevAt) {
403					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
404				}
405				prevAt = dr.At
406				if _, ok := c.index[dr.DeviceID]; !ok {
407					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
408				}
409				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
410					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
411				}
412				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
413					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
414				}
415				if dc.IDScheme == opIDSchemeLegacy {
416					// 旧方案标识可按（活动, 设备, 阶段）直接重算；新方案标识的
417					// 归属已在设备操作校验中确认，这里靠下方的历史对账锚定。
418					if wantOp := operationID(id, dr.DeviceID, dr.Stage); dr.OperationID != wantOp {
419						return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
420					}
421				}
422				if seenHistory[dr.OperationID] {
423					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
424				}
425				seenHistory[dr.OperationID] = true
426				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
427				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
428				want, ok := expected[dr.OperationID]
429				if !ok {
430					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
431				}
432				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
433					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
434				}
435				if !dr.Success && dr.Reason == "" {
436					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
437				}
438				o := want.op
439				if o.Success != dr.Success {
440					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
441				}
442				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
443				// 成功结果附带原因），故只对失败结果比对原因。
444				if !o.Success && o.Reason != dr.Reason {
445					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
446				}
447				// 时间按同一时刻判断，不因时区表示不同而冲突。
448				if !o.At.Equal(dr.At) {
449					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
450				}
451				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
452				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
453					if dr.Version != o.ResultVersion || dr.Version == "" {
454						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
455					}
456				} else if dr.Version != "" {
457					// 下载成功及任何失败结果都不携带版本。
458					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
459				}
460				c.Results = append(c.Results, ResultRecord{
461					DeviceID:    dr.DeviceID,
462					OperationID: dr.OperationID,
463					Stage:       dr.Stage,
464					Success:     dr.Success,
465					Reason:      dr.Reason,
466					Version:     dr.Version,
467					At:          dr.At,
468				})
469			}
470			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
471			for opID, want := range expected {
472				if !seenHistory[opID] {
473					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
474						ErrCorruptStorage, id, want.deviceID, want.stage)
475				}
476			}
477			out[id] = c
478		}
479		// 设备不能同时参加多个未结束活动。
480		busy := map[string]string{}
481		for id, c := range out {
482			if c.Ended {
483				continue
484			}
485			for _, cd := range c.Devices {
486				if other, ok := busy[cd.DeviceID]; ok {
487					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
488						ErrCorruptStorage, cd.DeviceID, other, id)
489				}
490				busy[cd.DeviceID] = id
491			}
492		}
493		s.campaigns = out
494		return nil
495	}
496	
497	func validDeviceStatus(status string) bool {
498		switch status {
499		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
500			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
501			DeviceAwaitingRollback, DeviceRollingBack,
502			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
503			return true
504		default:
505			return false
506		}
507	}
508	
509	// isRollbackTerminal 判断状态是否属于回滚相关终态。
510	func isRollbackTerminal(status string) bool {
511		switch status {
512		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
513			return true
514		default:
515			return false
516		}
517	}
518	
519	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
520	func isRollbackFlowStatus(status string) bool {
521		switch status {
522		case DeviceAwaitingRollback, DeviceRollingBack,
523			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
524			return true
525		default:
526			return false
527		}
528	}
529	
530	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
531	func validateRollbackDisk(campaignID string, dd diskDev) error {
532		bad := func(msg string) error {
533			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
534		}
535		rb := dd.Rollback
536		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
537		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
538		if dd.RollbackTarget != "" && !dd.Download.Claimed {
539			return bad("rollback target locked before download claim")
540		}
541		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
542		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
543			return bad("rollback status without locked target")
544		}
545		switch dd.Status {
546		case DeviceAwaitingRollback:
547			// 已接受安装失败、回滚尚未领取：回滚无结果。
548			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
549				return bad("awaiting rollback state mismatch")
550			}
551			if !(dd.Install.HasResult && !dd.Install.Success) {
552				return bad("awaiting rollback without install failure")
553			}
554		case DeviceRollingBack:
555			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
556				return bad("rolling back state mismatch")
557			}
558		case DeviceRollbackSucceeded:
559			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
560				return bad("rollback succeeded without success result")
561			}
562			if rb.ResultVersion != dd.RollbackTarget {
563				return bad("rollback version mismatch")
564			}
565			if _, ok := decodeObject(rb.ResultConfig); !ok {
566				return bad("rollback config invalid")
567			}
568		case DeviceRollbackFailed:
569			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
570				return bad("rollback failed without failure result")
571			}
572		case DeviceRollbackTimeout:
573			if dd.Phase != StageRollback {
574				return bad("rollback timeout phase mismatch")
575			}
576			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
577			if rb.HasResult {
578				return bad("rollback timeout with result")
579			}
580		default:
581			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
582			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
583			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
584			if dd.Install.HasResult && !dd.Install.Success {
585				return bad("install failure without rollback state")
586			}
587			if rb.Claimed || rb.HasResult {
588				return bad("rollback progressed without install failure")
589			}
590		}
591		return nil
592	}
