11	// activeCampaignSpec 构造一个在 base 之后 offset 时刻创建的单目标 v2 活动规格，
12	// 窗口为创建后一小时、截止为创建后两小时；与 upSpec 的时间线不相交，
13	// 用于在同一份存储里放入多个按正常流程无法同时创建的活动。
14	func activeCampaignSpec(id string, base time.Time, devices []string, batchSize int) CampaignSpec {
15		return CampaignSpec{
16			ID:            id,
17			Operator:      "bob",
18			CreatedAt:     base,
19			TargetVersion: "v2",
20			Devices:       devices,
21			BatchSize:     batchSize,
22			WindowStart:   base,
23			WindowEnd:     base.Add(time.Hour),
24			Deadline:      base.Add(2 * time.Hour),
25		}
26	}
27	
28	// mergeCampaignIntoStore 把 srcDir 存储里 campaignID 的活动磁盘记录原样合并进
29	// dstDir 的存储文件（两边的版本登记与设备集合此前已分别建好），返回写回字节。
30	// 用来构造“每个活动单独看都合法、放在一起才冲突”的多活动恢复数据。
31	func mergeCampaignIntoStore(t *testing.T, dstDir, srcDir, campaignID string) []byte {
32		t.Helper()
33		readDoc := func(dir string) map[string]any {
34			data, err := os.ReadFile(filepath.Join(dir, storeFileName))
35			if err != nil {
36				t.Fatal(err)
37			}
38			var doc map[string]any
39			if err := json.Unmarshal(data, &doc); err != nil {
40				t.Fatal(err)
41			}
42			return doc
43		}
44		dst := readDoc(dstDir)
45		src := readDoc(srcDir)
46		srcCampaign, ok := src["campaigns"].(map[string]any)[campaignID].(map[string]any)
47		if !ok {
48			t.Fatalf("source store has no campaign %s", campaignID)
49		}
50		dstCampaigns := dst["campaigns"].(map[string]any)
51		if _, exists := dstCampaigns[campaignID]; exists {
52			t.Fatalf("destination store already has campaign %s", campaignID)
53		}
54		dstCampaigns[campaignID] = srcCampaign
55		out, err := json.Marshal(dst)
56		if err != nil {
57			t.Fatal(err)
58		}
59		if err := os.WriteFile(filepath.Join(dstDir, storeFileName), out, 0o644); err != nil {
60			t.Fatal(err)
61		}
62		return out
63	}
64	
65	// TestRestoreOverlappingActiveCampaignsRefused 保护多个活动一同恢复时的活动设备
66	// 占用规则：同一台已登记设备出现在两项未结束活动中时，Open 必须返回
67	// ErrCorruptStorage，拒绝返回可用存储；不能只保留其中一项、删除重叠设备或把某项
68	// 活动改成结束，其余合法设备与活动也不能只恢复一部分。占用只看活动是否结束：
69	// 设备已安装成功但同批其他设备仍在等待时活动仍未结束；维护窗口不相交、设备离线
70	// 都不能提前解除占用。
71	func TestRestoreOverlappingActiveCampaignsRefused(t *testing.T) {
72		// 两项未结束活动以最普通的 pending 状态共用 d1。
73		t.Run("two pending campaigns share device", func(t *testing.T) {
74			s := setupUpgrade(t, "d1", "d2", "d3")
75			spec1 := activeCampaignSpec("cmp-1", upBase, []string{"d1", "d2"}, 2)
76			createCampaign(t, s, spec1)
77			dstDir := s.dir
78			if err := s.Close(); err != nil {
79				t.Fatal(err)
80			}
81	
82			src := setupUpgrade(t, "d1", "d2", "d3")
83			spec2 := activeCampaignSpec("cmp-2", upBase.Add(3*time.Hour), []string{"d1", "d3"}, 2)
84			createCampaign(t, src, spec2)
85			srcDir := src.dir
86			src.Close()
87	
88			original := mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
89			assertReopenCorrupt(t, dstDir, original)
90		})
91	
92		// d1 在 cmp-1 中已安装成功，但同批 d2 仍 pending，活动尚未结束：
93		// d1 依旧不能同时属于另一项未结束活动 cmp-2（其中 d3 合法也不允许只恢复它）。
94		t.Run("device succeeded but its campaign is still active", func(t *testing.T) {
95			s := setupUpgrade(t, "d1", "d2", "d3")
96			spec1 := activeCampaignSpec("cmp-1", upBase, []string{"d1", "d2"}, 2)
97			createCampaign(t, s, spec1)
98			bringOnline(t, s, "d1")
99			finishDevice(t, s, spec1, "d1", upBase)
100			cv := mustGetCampaign(s, "cmp-1")
101			if cv.Ended || cv.Status != CampaignRunning {
102				t.Fatalf("precondition: cmp-1 must stay running: %+v", cv)
103			}
104			if findDevice(cv, "d1").Status != DeviceSucceeded ||
105				findDevice(cv, "d2").Status != DevicePending {
106				t.Fatalf("precondition: d1 succeeded and d2 pending: %+v", cv.Devices)
107			}
108			dstDir := s.dir
109			s.Close()
110	
111			src := setupUpgrade(t, "d1", "d2", "d3")
112			spec2 := activeCampaignSpec("cmp-2", upBase.Add(3*time.Hour), []string{"d1", "d3"}, 2)
113			createCampaign(t, src, spec2)
114			srcDir := src.dir
115			src.Close()
116	
117			original := mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
118			assertReopenCorrupt(t, dstDir, original)
119		})
120	
121		// 叠加两个“看起来暂时领不到操作”的条件：两项活动维护窗口不相交，
122		// 且重叠设备此刻离线。占用判定不依赖窗口或在线状态，仍然必须拒绝打开。
123		// 同时让 d1 在第二项活动里已经走完下载（ready），证明任一活动中的进度
124		// 形态都不影响判定。
125		t.Run("disjoint windows and offline do not release device", func(t *testing.T) {
126			s := setupUpgrade(t, "d1", "d2", "d3")
127			spec1 := activeCampaignSpec("cmp-1", upBase, []string{"d1", "d2"}, 2)
128			createCampaign(t, s, spec1)
129			bringOnline(t, s, "d1")
130			finishDevice(t, s, spec1, "d1", upBase)
131			if err := s.SetOffline("d1"); err != nil {
132				t.Fatal(err)
133			}
134			if sh, _ := s.Get("d1"); sh.Online {
135				t.Fatal("precondition: d1 must be offline")
136			}
137			dstDir := s.dir
138			s.Close()
139	
140			src := setupUpgrade(t, "d1", "d2", "d3")
141			base2 := upBase.Add(3 * time.Hour) // 窗口 15:00–16:00，与 cmp-1 的 12:00–13:00 不相交
142			spec2 := activeCampaignSpec("cmp-2", base2, []string{"d1", "d3"}, 2)
143			createCampaign(t, src, spec2)
144			bringOnline(t, src, "d1")
145			dl, err := src.Claim(spec2.ID, "d1", base2)
146			if err != nil || dl == nil {
147				t.Fatalf("claim download: %v %+v", err, dl)
148			}
149			if err := src.SubmitResult(OperationResult{
150				CampaignID: spec2.ID, DeviceID: "d1", OperationID: dl.ID,
151				At: base2.Add(time.Minute), Success: true,
152			}); err != nil {
153				t.Fatalf("download result: %v", err)
154			}
155			if d := findDevice(mustGetCampaign(src, "cmp-2"), "d1"); d.Status != DeviceReady {
156				t.Fatalf("precondition: d1 ready in cmp-2, got %s", d.Status)
157			}
158			srcDir := src.dir
159			src.Close()
160	
161			original := mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
162			assertReopenCorrupt(t, dstDir, original)
163		})
164	}
