166	// TestRestoreEndedCampaignHistoryCoexistsWithActive 保护合法活动历史：
167	// 同一台设备可以留在已结束的旧活动中并参加新的未结束活动，合并恢复必须成功。
168	// GetCampaign 同时保留旧活动终态与历史、新活动当前进度；GetDeviceWork 只指向
169	// 新活动的待办，待办的阶段、操作标识与领取状态与保存时一致。
170	func TestRestoreEndedCampaignHistoryCoexistsWithActive(t *testing.T) {
171		// 新活动中 d1 已下载成功、安装尚未领取：待办应为未领取的安装操作。
172		t.Run("unclaimed install in new campaign", func(t *testing.T) {
173			s := setupUpgrade(t, "d1")
174			oldSpec := activeCampaignSpec("cmp-1", upBase, []string{"d1"}, 1)
175			createCampaign(t, s, oldSpec)
176			bringOnline(t, s, "d1")
177			finishDevice(t, s, oldSpec, "d1", upBase)
178			oldBefore := mustGetCampaign(s, "cmp-1")
179			if !oldBefore.Ended || oldBefore.Status != CampaignSucceeded {
180				t.Fatalf("precondition: cmp-1 must be ended: %+v", oldBefore)
181			}
182			dstDir := s.dir
183			s.Close()
184	
185			src := setupUpgrade(t, "d1")
186			base2 := upBase.Add(3 * time.Hour)
187			newSpec := activeCampaignSpec("cmp-2", base2, []string{"d1"}, 1)
188			createCampaign(t, src, newSpec)
189			bringOnline(t, src, "d1")
190			dl, err := src.Claim(newSpec.ID, "d1", base2)
191			if err != nil || dl == nil {
192				t.Fatalf("claim download: %v %+v", err, dl)
193			}
194			if err := src.SubmitResult(OperationResult{
195				CampaignID: newSpec.ID, DeviceID: "d1", OperationID: dl.ID,
196				At: base2.Add(time.Minute), Success: true,
197			}); err != nil {
198				t.Fatalf("download result: %v", err)
199			}
200			wantWork, err := src.GetDeviceWork("d1")
201			if err != nil {
202				t.Fatal(err)
203			}
204			srcDir := src.dir
205			src.Close()
206	
207			mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
208			s2, err := Open(dstDir)
209			if err != nil {
210				t.Fatalf("ended + active campaign sharing a device must open: %v", err)
211			}
212			defer s2.Close()
213	
214			// 旧活动终态与结果历史原样保留。
215			old := mustGetCampaign(s2, "cmp-1")
216			if !old.Ended || old.Status != CampaignSucceeded {
217				t.Fatalf("old campaign terminal state lost: %+v", old)
218			}
219			if findDevice(old, "d1").Status != DeviceSucceeded {
220				t.Fatalf("old campaign device state lost: %+v", findDevice(old, "d1"))
221			}
222			if len(old.Results) != len(oldBefore.Results) {
223				t.Fatalf("old history count changed: %+v vs %+v", old.Results, oldBefore.Results)
224			}
225			for i := range oldBefore.Results {
226				if old.Results[i] != oldBefore.Results[i] {
227					t.Fatalf("old history %d changed: %+v vs %+v", i, old.Results[i], oldBefore.Results[i])
228				}
229			}
230	
231			// 新活动当前进度保留：running、d1 ready、仅一条下载历史。
232			newC := mustGetCampaign(s2, "cmp-2")
233			if newC.Ended || newC.Status != CampaignRunning {
234				t.Fatalf("new campaign must stay running: %+v", newC)
235			}
236			if d := findDevice(newC, "d1"); d.Status != DeviceReady || d.Phase != StageInstall {
237				t.Fatalf("new campaign progress lost: %+v", d)
238			}
239			if len(newC.Results) != 1 || newC.Results[0].Stage != StageDownload ||
240				!newC.Results[0].Success {
241				t.Fatalf("new campaign history lost: %+v", newC.Results)
242			}
243	
244			// 待办指向新活动的未领取安装，阶段、操作标识、领取状态与保存时一致。
245			w, err := s2.GetDeviceWork("d1")
246			if err != nil {
247				t.Fatal(err)
248			}
249			if w.CampaignID != "cmp-2" {
250				t.Fatalf("work must point to active campaign cmp-2, got %q", w.CampaignID)
251			}
252			if w.Pending == nil {
253				t.Fatalf("pending install missing: %+v", w)
254			}
255			if w.Pending.Kind != StageInstall ||
256				w.Pending.ID != encodeOperationIDV2(0, "cmp-2", "d1", StageInstall) ||
257				w.PendingClaimed {
258				t.Fatalf("pending work changed after restore: %+v", w)
259			}
260			if wantWork.Pending == nil ||
261				w.Pending.ID != wantWork.Pending.ID ||
262				w.Pending.Kind != wantWork.Pending.Kind ||
263				w.PendingClaimed != wantWork.PendingClaimed {
264				t.Fatalf("pending work differs from saved state: %+v vs %+v", w, wantWork)
265			}
266		})
267	
268		// 新活动中 d1 已领取下载但尚未完成：重开后待办仍是同一个已领取下载标识，
269		// 领取状态不能因读取旧活动历史而丢失。
270		t.Run("claimed unfinished download in new campaign", func(t *testing.T) {
271			s := setupUpgrade(t, "d1")
272			oldSpec := activeCampaignSpec("cmp-1", upBase, []string{"d1"}, 1)
273			createCampaign(t, s, oldSpec)
274			bringOnline(t, s, "d1")
275			finishDevice(t, s, oldSpec, "d1", upBase)
276			dstDir := s.dir
277			s.Close()
278	
279			src := setupUpgrade(t, "d1")
280			base2 := upBase.Add(3 * time.Hour)
281			newSpec := activeCampaignSpec("cmp-2", base2, []string{"d1"}, 1)
282			createCampaign(t, src, newSpec)
283			bringOnline(t, src, "d1")
284			dl, err := src.Claim(newSpec.ID, "d1", base2)
285			if err != nil || dl == nil || dl.ID != encodeOperationIDV2(0, "cmp-2", "d1", StageDownload) {
286				t.Fatalf("claim download: %v %+v", err, dl)
287			}
288			wantWork, err := src.GetDeviceWork("d1")
289			if err != nil {
290				t.Fatal(err)
291			}
292			srcDir := src.dir
293			src.Close()
294	
295			mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
296			s2, err := Open(dstDir)
297			if err != nil {
298				t.Fatalf("ended + active campaign sharing a device must open: %v", err)
299			}
300			defer s2.Close()
301	
302			newC := mustGetCampaign(s2, "cmp-2")
303			if d := findDevice(newC, "d1"); d.Status != DeviceDownloading || d.Phase != StageDownload {
304				t.Fatalf("new campaign progress lost: %+v", d)
305			}
306			if len(newC.Results) != 0 {
307				t.Fatalf("claimed unfinished download must have no history: %+v", newC.Results)
308			}
309			w, err := s2.GetDeviceWork("d1")
310			if err != nil {
311				t.Fatal(err)
312			}
313			if w.CampaignID != "cmp-2" || w.Pending == nil {
314				t.Fatalf("work must point to cmp-2 pending op: %+v", w)
315			}
316			if w.Pending.Kind != StageDownload ||
317				w.Pending.ID != encodeOperationIDV2(0, "cmp-2", "d1", StageDownload) ||
318				!w.PendingClaimed {
319				t.Fatalf("claimed download not restored as saved: %+v", w)
320			}
321			if wantWork.Pending == nil ||
322				w.Pending.ID != wantWork.Pending.ID ||
323				w.Pending.Kind != wantWork.Pending.Kind ||
324				w.PendingClaimed != wantWork.PendingClaimed {
325				t.Fatalf("pending work differs from saved state: %+v vs %+v", w, wantWork)
326			}
327		})
328	}
329	
330	// TestRestoreMultipleActiveCampaignsDisjointDevices 多项未结束活动使用互不重叠
331	// 的设备集合时属于合法数据，必须一同正常打开，各设备待办仍指向各自的活动。
332	func TestRestoreMultipleActiveCampaignsDisjointDevices(t *testing.T) {
333		s := setupUpgrade(t, "d1", "d2", "d3")
334		spec1 := activeCampaignSpec("cmp-1", upBase, []string{"d1"}, 1)
335		createCampaign(t, s, spec1)
336		bringOnline(t, s, "d1")
337		dl, err := s.Claim(spec1.ID, "d1", upBase)
338		if err != nil {
339			t.Fatalf("claim d1 download: %v", err)
340		}
341		if err := s.SubmitResult(OperationResult{
342			CampaignID: spec1.ID, DeviceID: "d1", OperationID: dl.ID,
343			At: upBase.Add(time.Minute), Success: true,
344		}); err != nil {
345			t.Fatalf("d1 download: %v", err)
346		}
347		dstDir := s.dir
348		s.Close()
349	
350		src := setupUpgrade(t, "d1", "d2", "d3")
351		spec2 := activeCampaignSpec("cmp-2", upBase.Add(3*time.Hour), []string{"d2", "d3"}, 2)
352		createCampaign(t, src, spec2)
353		srcDir := src.dir
354		src.Close()
355	
356		mergeCampaignIntoStore(t, dstDir, srcDir, "cmp-2")
357		s2, err := Open(dstDir)
358		if err != nil {
359			t.Fatalf("active campaigns with disjoint device sets must open: %v", err)
360		}
361		defer s2.Close()
362	
363		c1 := mustGetCampaign(s2, "cmp-1")
364		c2 := mustGetCampaign(s2, "cmp-2")
365		if c1.Ended || c2.Ended || c1.Status != CampaignRunning || c2.Status != CampaignRunning {
366			t.Fatalf("both campaigns must be restored running: %+v %+v", c1.Status, c2.Status)
367		}
368		if findDevice(c1, "d1").Status != DeviceReady {
369			t.Fatalf("cmp-1 progress lost: %+v", findDevice(c1, "d1"))
370		}
371		if findDevice(c2, "d2").Status != DevicePending || findDevice(c2, "d3").Status != DevicePending {
372			t.Fatalf("cmp-2 devices lost: %+v %+v", findDevice(c2, "d2"), findDevice(c2, "d3"))
373		}
374	
375		w1, err := s2.GetDeviceWork("d1")
376		if err != nil {
377			t.Fatal(err)
378		}
379		if w1.CampaignID != "cmp-1" || w1.Pending == nil ||
380			w1.Pending.Kind != StageInstall || w1.PendingClaimed {
381			t.Fatalf("d1 work must point at cmp-1 install: %+v", w1)
382		}
383		for _, id := range []string{"d2", "d3"} {
384			w, err := s2.GetDeviceWork(id)
385			if err != nil {
386				t.Fatal(err)
387			}
388			if w.CampaignID != "cmp-2" || w.Pending == nil ||
389				w.Pending.Kind != StageDownload || w.PendingClaimed {
