1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	// rewriteStore 读入已保存的存储文件，用 mutate 改写后写回，返回写回后的字节
13	// （即拒绝打开时必须原样保留的损坏内容）。
14	func rewriteStoreBytes(t *testing.T, dir string, mutate func(map[string]any)) []byte {
15		t.Helper()
16		path := filepath.Join(dir, storeFileName)
17		data, err := os.ReadFile(path)
18		if err != nil {
19			t.Fatal(err)
20		}
21		var doc map[string]any
22		if err := json.Unmarshal(data, &doc); err != nil {
23			t.Fatal(err)
24		}
25		mutate(doc)
26		out, err := json.Marshal(doc)
27		if err != nil {
28			t.Fatal(err)
29		}
30		if err := os.WriteFile(path, out, 0o644); err != nil {
31			t.Fatal(err)
32		}
33		return out
