338	// TestResultHistoryRollbackStatesReopen 覆盖回滚开关开启后的各阶段对账。
339	func TestResultHistoryRollbackStatesReopen(t *testing.T) {
340		// 安装失败 → 等待回滚 / 正在回滚 / 回滚超时：安装失败历史保留，
