356				}
357				if err := s.AdvanceCampaign(spec.ID, spec.Deadline); err != nil {
358					t.Fatal(err)
359				}
360			}, DeviceRollbackTimeout},
361		} {
362			t.Run(tc.name, func(t *testing.T) {
363				s, dir, spec, _ := setupInstallFailure(t, true)
364				tc.advance(s, spec)
365				if err := s.Close(); err != nil {
366					t.Fatal(err)
367				}
